SELECT * FROM (
    SELECT t.*, ROWNUM rn FROM (
        SELECT 

        WHERE r.IS_DELETED = 0
         AND r.TYPE_ID   = #{typeId} 
         AND r.STATUS    = #{status} 
         AND r.FLOOR_NUM = #{floorNum} 
         AND r.ROOM_NO LIKE '%' || #{keyword} || '%' 

    ) t WHERE ROWNUM <= #{offset} + #{limit}
) WHERE rn > #{offset}

SELECT COUNT(1) FROM ROOM r WHERE r.IS_DELETED = 0
 AND r.TYPE_ID   = #{typeId} 
 AND r.STATUS    = #{status} 
 AND r.FLOOR_NUM = #{floorNum} 
 AND r.ROOM_NO LIKE '%' || #{keyword} || '%'

