UPDATE ROOM SET
    STATUS = #{status},
    VERSION = VERSION + 1,
    UPDATE_TIME = F_NOW(),
    UPDATE_BY = #{updateBy}
WHERE ROOM_ID = #{roomId} AND VERSION = #{version}
